'use strict';
let story, state={path:'',page:0,view:'home',started:false}, saved=null;
const KEY='last-tool.v1',app=document.getElementById('app'),modal=document.getElementById('modal');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=p=>p.split('').map((x,i)=>(i+1)+x).join(' → ');
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&/^[AB]{0,3}$/.test(s.path)&&Number.isInteger(s.page)&&s.page>=0&&['read','result'].includes(s.view)&&s.started)saved=s;}catch{}}
function persist(){if(!state.started)return; saved={...state};try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{toast('이 브라우저에서는 진행을 저장할 수 없습니다.');}document.getElementById('resumeNav').hidden=false;}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3500);}
function go(view){if(view!=='read'&&VN.active)VN.stop();state.view=view;render();window.scrollTo(0,0);if(['read','result'].includes(view))persist();}
function chunks(text){const sentences=text.match(/[^.!?。！？]+(?:[.!?。！？]+["”']?|$)|[.!?。！？]+/g)||[text];const pages=[];let group='';for(const s of sentences){if(group.length+s.length>700&&group){pages.push(group);group='';}group+=s;}if(group)pages.push(group);return pages;}
function prose(t){const sentences=t.match(/[^.!?。！？]+(?:[.!?。！？]+["”']?|$)|[.!?。！？]+/g)||[t];let ps=[],g='';for(const s of sentences){g+=s;if(g.length>190){ps.push(g);g='';}}if(g)ps.push(g);return ps.map(x=>'<p>'+esc(x.trim())+'</p>').join('');}
function gameHome(){app.innerHTML=`<section class="title-screen"><div class="title-world" aria-hidden="true"><div class="title-window"></div><div class="title-window second"></div><div class="title-floor"></div><div class="title-lantern"><i></i></div><div class="title-sprite title-master"></div><div class="title-sprite title-yun"></div><div class="title-desk"><i>靈</i><i>文</i></div><div class="title-dust"></div></div><div class="title-copy"><p class="title-kicker">一七九二 · 한양의 작은 각방</p><h1>마지막 도구</h1><p class="title-sub">외날의 창칼</p><p class="title-hook">한 획을 끝까지 지킬 것인가.<br>그다음 손을 남길 것인가.</p><div class="title-buttons">${saved?'<button class="title-primary" data-action="resume">이어 읽기 <span>→</span></button>':''}<button class="${saved?'title-secondary':'title-primary'}" data-action="setup">${saved?'새로운 삶 시작':'이야기 시작'} <span>→</span></button><button class="title-secondary" data-action="about">작품과 조작 안내</button></div><p class="title-small">도트 비주얼 노벨 · 세 번의 선택 · 서로 다른 유산</p></div><div class="title-bottom"><span>문장을 줄이지 않고, 한 장면씩.</span><button data-action="notes">원작과 수록 범위 ↗</button></div></section>`;}
function gameSetup(){app.innerHTML=`<section class="reading-setup"><span class="eyebrow">삶에 들어서기 전 · 출발점</span><h1>한 치의 어긋남도<br>그냥 지나치지 못하는 사람.</h1><p>이번 이야기는 원고에 설정된 가상 기질에서 시작합니다.<br>정해진 기질이 당신의 선택이나 결말을 결정하지는 않습니다.</p><div class="lens"><span class="character">辛</span><span class="eyebrow">원고의 가상 기질 · 辛金</span><h2>서릿발 맺힌 쇠의 결</h2><p>남이 그냥 넘기는 반 푼의 어긋남도 눈으로 먼저 보아 넘기지 못하고, 제 손끝으로 기어이 다시 깎아내야 직성이 풀리는 기질.</p><details><summary>강점과 그 대가</summary><p>어미자의 얇은 인서체(印書體) 가로획 뿌리를 비스듬히 세워 부러지지 않게 파내는 솜씨는 도성 으뜸이다. 그러나 제자가 파놓은 획의 미세한 흔들림을 참지 못해 밤마다 칼을 빼앗아 고쳐 파니, 수제자는 육 년째 어미자 한 개를 온전히 맡지 못하고 모든 과부하가 주인공의 앓는 손목으로 쏠린다.</p></details></div><p>당신은 교서관 경공장 명부에 오른 숙련 각자장입니다. 내각에 바칠 활자와 당장 식구들을 먹일 책판. 두 납기가 겹치는 밤, 이야기가 시작됩니다.</p><div class="notice">생년월일을 이용한 사주 계산·음력 변환·역사 인물 매칭은 아직 제공하지 않습니다. 개인정보를 입력하지 않고 원고의 기질로 체험할 수 있습니다.</div><button class="primary" data-action="start">1792년의 각방으로 <span>→</span></button><button class="understated" data-action="firstcard">출발점 카드 저장</button></section>`;}
function home(){Sidae.home();}
function setup(){Sidae.setup();}
function result(){Sidae.result();}
function read(){VN.mount();}
function choiceAt(i,p){return story.choices[p.slice(0,i)][p[i]==='A'?0:1];}
function quoteFor(p){return story.reflection[p]?.quote||story.outcomes[p].legacy.replace(/^\[[^\]]+\]\s*/,'');}
function gameResult(){const p=state.path,o=story.outcomes[p],r=story.reflection[p];if(!o){go('home');return;}app.innerHTML=`<section class="result"><div class="result-intro"><span class="eyebrow">이번 삶이 남긴 것</span><h1>손이 멈춘 뒤에도,<br>남는 것이 있습니다.</h1><p style="font-size:12px;color:var(--muted)">1792년 한양 · 각자장 · ${route(p)}</p></div><div class="result-card"><span class="eyebrow">${r?'나의 생애 한 문장':'분기표 원문 · 나의 유산'}</span><blockquote>${esc(quoteFor(p))}</blockquote><div class="card-bottom"><span>마지막 도구 — 외날의 창칼</span><span>선택의 기록 ${route(p)}</span></div></div><div class="actions"><button class="primary" data-action="download">생애 카드 저장 <span>↓</span></button><button class="secondary" data-action="share">결과 문장 공유 ↗</button><button class="secondary" data-action="reread">결말 다시 읽기</button></div><section class="result-section"><h2>출발점과 이번 선택</h2><p>출발점은 ‘서릿발 맺힌 쇠의 결’이었습니다. 완결을 추구하지만, 다른 손을 믿기 어려운 가상 기질입니다.</p><p>${esc(r?r.text:o.event)}</p>${!r?'<small>회고를 새로 생성하지 않고 분기표의 인과관계 원문을 표시합니다.</small>':''}</section><section class="result-section"><h2>곁에 남은 사람, 달라진 관계</h2><p>${esc(o.relations)}</p></section><section class="result-section"><h2>마지막 도구의 행방</h2><p>${esc(o.tool)}</p></section><section class="result-section"><h2>남긴 유산과 감수한 대가</h2><p>${esc(o.legacy)}</p><p>${esc(o.cost)}</p></section><section class="result-section"><h2>세 번의 선택</h2>${p.split('').map((v,i)=>`<p><small>0${i+1} · ${v}</small>　${esc(choiceAt(i,p).title)}</p>`).join('')}</section><div class="notice">이 결과는 이번 회차의 창작 속 삶을 설명합니다. 실제 성격·운명·수명에 대한 진단이 아닙니다. 원고의 두 완성 경로 외 여섯 경로는 분기표 원문으로 제공됩니다.</div><div class="actions"><button class="primary" data-action="replay">같은 출발점, 다른 선택 →</button><button class="secondary" data-action="home">처음 화면으로</button></div><p style="font-size:12px;color:var(--muted)">다시 체험하면 현재 이어 읽기 기록을 새 회차로 바꿉니다. 남기고 싶은 결과는 카드로 저장해 주세요.</p></section>`;}
function render(){document.getElementById('resumeNav').hidden=!saved;({home,setup,read,result}[state.view]||home)();}
function openModal(html){document.getElementById('modalBody').innerHTML=html;modal.showModal();modal.scrollTop=0;}
function notes(){openModal(`<h2>원고와 역사, 구분하여 읽기</h2><p>기존 공통 도입과 두 완성 소설 경로는 보존했습니다. 추가 첨부된 네 PDF를 대조해, 분기표로만 이어지던 두 연결 장면과 여섯 결말을 대사와 서술로 보충했습니다. 중복 설명과 작가용 안내는 제외하고 사건·행동·감정의 연결을 살렸습니다. 추가 장면은 전문을 그대로 옮긴 판본이 아니라 읽기용 편집본입니다.</p><p>장인과 윤서·춘삼·최도윤, 계약과 갈등, 개인의 후일담은 창작입니다. 원고에 설정된 辛金은 사용자 생년월일로 산출한 일간이 아닙니다.</p><h3>실제 역사</h3><p>생생자는 1792년 황양목으로 제작한 목활자입니다. 정리자는 그 뒤 생생자를 바탕으로 제작되었습니다. 작품의 관청 명단·개인별 물량·눈금틀과 도구의 전수는 역사 기록으로 확인된 사건이 아닙니다. 원고의 후일담 연대와 책 간행 시점에는 별도의 고증이 필요한 부분이 있어 실제 역사로 단정하지 않습니다.</p><p><a href="https://encykorea.aks.ac.kr/Article/E0027516" target="_blank" rel="noopener">생생자 · 한국민족문화대백과사전 ↗</a></p><h3>제공 범위</h3><p>장인의 삶 한 편, 세 번의 선택과 8개 엔딩, 사전 가치관과 선택 비교, 이미지 카드 저장을 제공합니다. 다른 추천 인물의 체험 게임은 제공하지 않습니다.</p><p><a href="manuscript.pdf" target="_blank" rel="noopener">기존 원본 PDF 열기 ↗</a></p><button class="secondary" data-sd="method">만세력·추천의 계산 기준</button>`);}
function wrap(ctx,text,max){const lines=[];let l='';for(const ch of text){if(ctx.measureText(l+ch).width>max){lines.push(l);l=ch;}else l+=ch;}if(l)lines.push(l);return lines;}
async function download(first=false){try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#31453c';ctx.fillRect(0,0,1080,1350);ctx.strokeStyle='#aeb9a0';ctx.strokeRect(55,55,970,1240);ctx.fillStyle='#d8dbc9';ctx.font='24px sans-serif';ctx.fillText('마지막 도구  /  '+(first?'출발점의 기록':'이번 삶의 기록'),100,150);ctx.font='20px sans-serif';ctx.fillText('1792년 한양 · 각자장',100,215);ctx.font='46px serif';const q=first?'서릿발 맺힌 쇠의 결\n한 치의 어긋남도 그냥 지나치지 못하는 사람.':quoteFor(state.path);let y=365;for(const part of q.split('\n'))for(const l of wrap(ctx,part,860)){ctx.fillText(l,100,y);y+=80;}ctx.font='24px sans-serif';y=Math.max(y+90,900);const details=first?'원고에 설정된 가상 기질 · 사주 계산 결과가 아닙니다.':story.outcomes[state.path].tool;for(const l of wrap(ctx,details,860)){ctx.fillText(l,100,y);y+=43;}ctx.font='20px sans-serif';ctx.fillText(first?'주어진 해석보다, 내가 한 선택이 더 오래 남는다.':'선택의 기록  '+route(state.path),100,1190);ctx.font='17px sans-serif';ctx.fillText('선택형 역사소설 · 창작 속의 삶',100,1240);canvas.toBlob(blob=>{if(!blob){toast('카드를 만들지 못했습니다. 다시 시도해 주세요.');return;}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='마지막도구_'+(first?'출발점':state.path)+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('카드 이미지를 저장했습니다.');},'image/png');}catch{toast('카드 저장에 실패했습니다. 결과 문장 공유를 이용해 주세요.');}}
async function share(){const text=quoteFor(state.path)+'\n— 마지막 도구 · '+route(state.path);try{if(navigator.share)await navigator.share({title:'마지막 도구 · 이번 삶의 기록',text});else{await navigator.clipboard.writeText(text);toast('결과 문장을 복사했습니다.');}}catch(e){if(e.name!=='AbortError')openModal('<h2>결과 문장</h2><p>아래 문장을 선택해 복사해 주세요.</p><textarea readonly style="width:100%;min-height:160px;padding:15px;font:inherit">'+esc(text)+'</textarea>');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'home':go('home');break;case'setup':go('setup');break;case'start':case'replay':state={path:'',beat:0,page:0,phase:'text',view:'read',started:true};Sidae.begin();go('read');break;case'resume':if(saved){state={...saved};go(state.view);}break;case'result':go('result');break;case'reread':state.beat=0;state.phase='text';go('read');break;case'close':modal.close();break;case'notes':notes();break;case'characters':openModal('<h2>곁에 있는 사람들</h2>'+story.characters.map(c=>'<h3>'+esc(c.name)+'</h3><p>'+esc(c.text)+'</p>').join(''));break;case'privacy':openModal('<h2>이 브라우저에만 남는 기록</h2><p>선택 경로와 현재 읽는 문장, 읽기 설정을 이 브라우저에 저장합니다. 다른 기기와 자동 동기화되지 않습니다. 출생 정보는 기기에서 계산하고 저장하지 않습니다. 선택한 경우 분석 결과를 저장하며, 게임 회차에는 사전 가치관 답변과 선택 시각이 함께 저장됩니다.</p><button class="secondary" data-action="clear">이어 읽기 기록 삭제</button>');break;case'clear':try{localStorage.removeItem(KEY);localStorage.removeItem('sidae.profile.v1');Sidae.profile=null;}catch{}saved=null;state={path:'',beat:0,page:0,view:'home',started:false};modal.close();go('home');toast('이어 읽기 기록을 삭제했습니다.');break;case'about':openModal('<h2>한 장면씩, 당신의 속도로</h2><p>화면 어디든 누르거나 Space·Enter를 누르면 진행합니다. 글자가 나타나는 중에는 현재 문장을 완성하고, 다시 누르면 다음 대사 또는 내레이션으로 넘어갑니다. 선택지는 장면을 끝까지 읽은 뒤 나타납니다.</p><p>대사는 이름이 붙은 말풍선에, 행동과 심리·상황은 내레이션 창에 표시됩니다. 대사가 없는 인물도 장면에 남아 있으며, 원작의 등장·퇴장에 따라 이동합니다.</p><p>대화 기록, 자동 진행, 글자 크기·속도, 동작 줄이기, 효과음 설정을 지원합니다. 자동 진행은 선택지 앞에서 멈춥니다. 효과음은 기본 꺼짐입니다.</p><p>기존 두 완성 경로를 보존하고 추가 원고를 바탕으로 나머지 여섯 결말과 연결 장면을 보충했습니다. 시대인재 첫 화면에서 출생 정보와 가치관을 입력하면 계산과 추천을 받을 수 있습니다.</p>');break;case'download':download();break;case'firstcard':download(true);break;case'share':share();break;}});
modal.addEventListener('close',()=>{if(!VN.active)return;VN.modalPaused=false;if(VN.engine.typing)VN.startTyping();else VN.scheduleAuto();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
Promise.all(['story.json','novel.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('load');return r.json();}))).then(([d,book])=>{story=d;VN.book=book;load();render();}).catch(()=>{app.innerHTML='<section class="reading-setup"><h1>원고를 불러오지 못했습니다.</h1><p>연결을 확인한 뒤 새로고침해 주세요. 저장된 선택은 유지됩니다.</p><button class="secondary" onclick="location.reload()">다시 불러오기</button></section>';});
